:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #233d38;
  background: #f4f0e8;
  font-size: 16px;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #f4f0e8;
  background-image: radial-gradient(#d8d0be 1px, transparent 1px);
  background-size: 20px 20px;
}

.card {
  width: min(100%, 520px);
  padding: clamp(24px, 7vw, 48px);
  border: 1px solid #d8d0be;
  border-radius: 24px;
  background: #fffdf8;
  box-shadow: 0 18px 50px rgb(35 61 56 / 10%);
}

.header { text-align: center; }
.eyebrow, .result-label {
  color: #b45e43;
  font-size: 0.9rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 12px 0 8px;
  font-size: clamp(2.4rem, 9vw, 3.6rem);
  line-height: 0.98;
  letter-spacing: -0.06em;
}

h1 span { color: #287764; }
.header p { margin: 14px 0 32px; color: #566a63; font-size: 1.05rem; }
.fractions { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 16px; }

.fraction {
  min-width: 0;
  margin: 0;
  padding: 16px;
  border: 1px solid #d8d0be;
  border-radius: 16px;
  background: #f8f5ed;
}

.fraction legend { padding: 0 6px; color: #566a63; font-size: 0.9rem; font-weight: 700; }
.fraction label { display: block; margin: 0 0 5px; color: #566a63; font-size: 0.9rem; }
.fraction input {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 8px 10px;
  border: 1px solid #c8c0ae;
  border-radius: 9px;
  background: #fffdf8;
  color: #233d38;
  font: inherit;
  font-size: 1.15rem;
  text-align: center;
}

.fraction input:focus-visible, button:focus-visible { outline: 3px solid #d9955c; outline-offset: 3px; }
.fraction-line { display: block; height: 2px; margin: 9px 0; border-radius: 2px; background: #287764; }
.operator-hint { color: #b45e43; font-size: 0.85rem; font-weight: 750; text-transform: uppercase; }

.operations { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin: 24px 0; }
.operations button {
  min-height: 54px;
  border: 1px solid #287764;
  border-radius: 12px;
  background: #287764;
  color: #fffdf8;
  cursor: pointer;
  font: inherit;
  font-size: 1.6rem;
  font-weight: 700;
  transition: background-color 120ms ease, transform 120ms ease, box-shadow 120ms ease;
}
.operations button:hover { background: #1d5f51; box-shadow: 0 5px 12px rgb(35 61 56 / 15%); }
.operations button:active { transform: translateY(2px); background: #174a40; }

.result {
  padding: 24px 16px;
  border-radius: 16px;
  background: #e9f1e9;
  text-align: center;
}

.result-label { font-size: 0.82rem; }
.answer { margin-top: 10px; color: #233d38; font-size: clamp(2.5rem, 10vw, 3.5rem); font-weight: 750; line-height: 1.1; letter-spacing: -0.04em; overflow-wrap: anywhere; }
.decimal { margin: 8px 0 0; color: #566a63; font-size: 1.05rem; }
.error { margin: 12px 0 0; color: #9b352b; font-weight: 700; }
[hidden] { display: none !important; }
footer { margin-top: 24px; color: #718078; font-size: 0.9rem; text-align: center; }
footer span { padding-left: 4px; color: #b45e43; }

@media (max-width: 390px) {
  .card { padding: 24px 18px; }
  .fractions { gap: 9px; }
  .fraction { padding: 13px 10px; }
  .operations { gap: 8px; }
}

const form = document.querySelector("#calculator");
const result = document.querySelector("#fraction-result");
const decimal = document.querySelector("#decimal-result");
const error = document.querySelector("#error-message");

function gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b) [a, b] = [b, a % b];
  return a || 1;
}

function readFraction(numeratorId, denominatorId) {
  const numeratorInput = document.getElementById(numeratorId);
  const denominatorInput = document.getElementById(denominatorId);
  const numerator = numeratorInput.valueAsNumber;
  const denominator = denominatorInput.valueAsNumber;
  if (!Number.isInteger(numerator) || !Number.isInteger(denominator)) {
    throw new Error("Enter whole numbers for both numerator and denominator.");
  }
  if (denominator === 0) throw new Error("A denominator cannot be zero.");
  return { numerator, denominator };
}

function reduce(numerator, denominator) {
  if (denominator < 0) {
    numerator = -numerator;
    denominator = -denominator;
  }
  const divisor = gcd(numerator, denominator);
  return { numerator: numerator / divisor, denominator: denominator / divisor };
}

function calculate(operation) {
  error.hidden = true;
  error.textContent = "";
  try {
    const a = readFraction("num1", "den1");
    const b = readFraction("num2", "den2");
    let numerator;
    let denominator;

    if (operation === "add" || operation === "subtract") {
      const sign = operation === "add" ? 1 : -1;
      numerator = a.numerator * b.denominator + sign * b.numerator * a.denominator;
      denominator = a.denominator * b.denominator;
    } else if (operation === "multiply") {
      numerator = a.numerator * b.numerator;
      denominator = a.denominator * b.denominator;
    } else {
      if (b.numerator === 0) throw new Error("Cannot divide by a fraction equal to zero.");
      numerator = a.numerator * b.denominator;
      denominator = a.denominator * b.numerator;
    }

    const answer = reduce(numerator, denominator);
    result.textContent = `${answer.numerator}/${answer.denominator}`;
    decimal.textContent = `Decimal: ${(answer.numerator / answer.denominator).toFixed(3)}`;
  } catch (err) {
    result.textContent = "—";
    decimal.textContent = "Choose an operation to begin";
    error.textContent = err.message;
    error.hidden = false;
  }
}

form.addEventListener("click", (event) => {
  const button = event.target.closest("button[data-operation]");
  if (button) calculate(button.dataset.operation);
});
